import {LEGAL_ADMIN_LABELS,LEGACY_LEGAL_ADMIN_TITLES} from './legal-admin-labels.js';
import {Storage} from '@google-cloud/storage';import multer from 'multer';import type {Request,Response,Router,NextFunction} from 'express';import {randomUUID} from 'node:crypto';
import type {FirebaseService} from './firebase.service.js';import {platformManagement} from './asset-delegation.js';import {documentRouteParam} from './legal-route-param.js';
import {LEGAL_LANGUAGES,LEGAL_ROLES,legalFileHash,legalHash,legalReference,legalPublicationProblems,legalReleasePublished} from './legal-publication.js';
const fail=(error:string,status=400)=>Object.assign(Error(error),{status});
const upload=multer({storage:multer.memoryStorage(),limits:{fileSize:6*1024*1024,files:1,fields:10,parts:11,fieldSize:400000}}).single('file');
export class LegalAdminService{
 private storage=new Storage({keyFilename:process.env.GCS_SERVICE_ACCOUNT||process.env.FIREBASE_SERVICE_ACCOUNT||undefined});
 constructor(private store:FirebaseService){}
 async init(){await this.store.db.ref('publicContent/legalAdminLabels').transaction((old:any)=>{if(!old)return LEGAL_ADMIN_LABELS;for(const [lang,copy]of Object.entries(LEGAL_ADMIN_LABELS)){old[lang]??={};for(const [key,value]of Object.entries(copy))if(old[lang][key]===undefined||(key==='title'&&old[lang][key]===LEGACY_LEGAL_ADMIN_TITLES[lang]))old[lang][key]=value;}return old;});}
 private async admin(req:Request){const token=/^Bearer (.+)$/.exec(req.headers.authorization||'')?.[1];if(!token)throw fail('authentication_required',401);let u:any;try{u=await this.store.auth.verifyIdToken(token,true);}catch{throw fail('invalid_authentication',401);}const p=(await this.store.db.ref('backendusers/'+u.uid).once('value')).val();if(!platformManagement({backendusers:{[u.uid]:p}},u.uid,u))throw fail('admin_required',403);return u;}
 private async read(){return (await this.store.db.ref('publicContent/legal').once('value')).val()||{releases:{}};}
 private async change(u:any,revision:string,fn:(legal:any)=>void){if(!/^[a-f0-9]{64}$/.test(revision||''))throw fail('legal_changed',409);const ref=this.store.db.ref(),auditId=randomUUID();await ref.once('value');const result=await ref.transaction(root=>{if(root===null)return null;if(!platformManagement(root,u.uid,u))return;root.publicContent??={};const legal=root.publicContent.legal??={releases:{}};if(legalHash(legal)!==revision)return;fn(legal);root.publicContent.legalAudit??={};root.publicContent.legalAudit[auditId]={by:u.uid,at:new Date().toISOString(),activeRelease:legal.activeRelease||'',draftRelease:legal.draftRelease||''};return root;},undefined,false);if(!result.committed||!result.snapshot.val()?.publicContent?.legalAudit?.[auditId])throw fail('legal_changed',409);}
 private draft(legal:any){const id=legal.draftRelease,r=legal.releases?.[id];if(!r||r.status!=='draft')throw fail('legal_draft_required',409);return {id,r};}
 private async bucket(){const b=this.storage.bucket('ailla-poc.appspot.com');const [m]=await b.getMetadata();if(m.iamConfiguration?.publicAccessPrevention!=='enforced')throw fail('private_document_bucket_required',503);return{bucket:b,uniform:m.iamConfiguration?.uniformBucketLevelAccess?.enabled===true};}
 state=async(req:Request,res:Response)=>{await this.admin(req);await this.init();const legal=await this.read();res.set('Cache-Control','private, no-store').json({revision:legalHash(legal),activeRelease:legal.activeRelease||'',activePublished:legalReleasePublished(legal.releases?.[legal.activeRelease]),canResumeActive:!legal.draftRelease&&legal.releases?.[legal.activeRelease]?.status==='draft',draftRelease:legal.draftRelease||'',active:legal.releases?.[legal.activeRelease]||null,draft:legal.releases?.[legal.draftRelease]||null,problems:legal.draftRelease?legalPublicationProblems(legal.releases?.[legal.draftRelease]):[],labels:(await this.store.db.ref('publicContent/legalAdminLabels').once('value')).val()||{}});};
 resume=async(req:Request,res:Response)=>{const u=await this.admin(req);await this.change(u,req.body.revision,legal=>{if(legal.draftRelease)throw fail('legal_draft_exists',409);const id=legal.activeRelease,r=legal.releases?.[id];if(!id||r?.status!=='draft')throw fail('legal_draft_required',409);legal.draftRelease=id;});res.json({ok:true});};
 create=async(req:Request,res:Response)=>{const u=await this.admin(req);await this.change(u,req.body.revision,legal=>{if(legal.draftRelease&&legal.releases?.[legal.draftRelease]?.status==='draft')throw fail('legal_draft_exists',409);const id='gd-legal-'+Date.now()+'-'+randomUUID().slice(0,8),source=legal.releases?.[legal.activeRelease];const r=source?JSON.parse(JSON.stringify(source)):{documents:{},languages:LEGAL_LANGUAGES};r.documents??={};r.status='draft';delete r.publication;r.createdBy=u.uid;r.createdAt=new Date().toISOString();for(const role of LEGAL_ROLES){r.documents[role]??={};for(const language of LEGAL_LANGUAGES)r.documents[role][language]??={id:role,language,title:'',version:'',text:''};}legal.releases??={};legal.releases[id]=r;legal.draftRelease=id;});res.json({ok:true});};
 save=async(req:Request,res:Response)=>{const u=await this.admin(req);await new Promise<void>((resolve,reject)=>upload(req,res,e=>e?reject(fail('legal_upload_invalid')):resolve()));const b=req.body,role=String(b.role||''),language=String(b.language||'');if(!LEGAL_ROLES.includes(role)||!LEGAL_LANGUAGES.includes(language)||b.reviewed!=='true')throw fail('legal_review_required');const title=String(b.title||'').trim(),version=String(b.version||'').trim();if(!title||title.length>240||!version||version.length>80)throw fail('legal_fields_invalid');let text=String(b.text||'').trim(),attachment:any,object:any;const file=req.file;if(file){const ext=file.originalname.toLowerCase().split('.').pop();if(['txt','md'].includes(ext||'')){try{text=new TextDecoder('utf-8',{fatal:true}).decode(file.buffer).replace(/^\uFEFF/,'').trim();}catch{throw fail('legal_utf8_required');}attachment=null;}else if(ext==='pdf'&&file.buffer.subarray(0,5).toString()==='%PDF-'){const legal=await this.read();if(legalHash(legal)!==b.revision)throw fail('legal_changed',409);const {id}=this.draft(legal),{bucket,uniform}=await this.bucket(),path=`assets/legal/releases/${id}/${role}/${language}/${randomUUID()}.pdf`;object=bucket.file(path);await object.save(file.buffer,{resumable:false,contentType:'application/pdf',preconditionOpts:{ifGenerationMatch:0},...(!uniform?{predefinedAcl:'private' as const}:{}),metadata:{cacheControl:'private, no-store'}});attachment={bucket:'ailla-poc.appspot.com',path,sha256:legalFileHash(file.buffer),size:file.size,filename:file.originalname.replace(/[\r\n\x00/\\]/g,'_').slice(0,160)};}else throw fail('legal_file_type');}if(text.length<20||text.length>250000){if(object)await object.delete({ignoreNotFound:true}).catch(()=>{});throw fail('legal_text_required');}
 try{await this.change(u,b.revision,legal=>{const {r}=this.draft(legal),old=r.documents?.[role]?.[language]||{},d:any={id:role,language,title,version,text,sourceVersion:r.documents?.[role]?.fr?.version||version,referenceText:r.documents?.[role]?.fr?.text||'',...(old.attachment?{attachment:old.attachment}:{})};if(attachment===null)delete d.attachment;else if(attachment)d.attachment=attachment;if(language==='fr'){d.sourceVersion=version;d.referenceText=text;d.reviewedReference=legalReference(d);}else d.reviewedReference=legalReference(r.documents?.[role]?.fr);r.documents[role][language]=d;r.updatedAt=new Date().toISOString();});}catch(e){if(object)await object.delete({ignoreNotFound:true}).catch(()=>{});throw e;}res.json({ok:true});};
 publish=async(req:Request,res:Response)=>{const u=await this.admin(req);if(req.body.confirmed!==true)throw fail('legal_publication_confirmation_required');await this.change(u,req.body.revision,legal=>{const {id,r}=this.draft(legal),problems=legalPublicationProblems(r);if(problems.length)throw Object.assign(fail('legal_incomplete',409),{problems});for(const role of LEGAL_ROLES)for(const language of LEGAL_LANGUAGES){r.documents[role][language].referenceText=r.documents[role].fr.text;r.documents[role][language].sourceVersion=r.documents[role].fr.version;}r.languages=LEGAL_LANGUAGES;r.status='published';r.publication={method:'admin-ui',by:u.uid,at:new Date().toISOString(),contentHash:legalHash(r.documents)};legal.activeRelease=id;delete legal.draftRelease;});res.json({ok:true});};
 private async sendFile(res:Response,release:string,role:string,language:string,admin=false){const legal=await this.read(),r=legal.releases?.[release];if(!r||(!admin&&r.status!=='published'))throw fail('legal_file_not_found',404);const a=r.documents?.[role]?.[language]?.attachment;if(!a||a.bucket!=='ailla-poc.appspot.com'||!a.path.startsWith(`assets/legal/releases/`)||!new RegExp(`^assets/legal/releases/[a-zA-Z0-9_-]+/${role}/${language}/[a-f0-9-]+\\.pdf$`).test(a.path))throw fail('legal_file_not_found',404);const {bucket}=await this.bucket(),file=bucket.file(a.path),[m]=await file.getMetadata();if(Number(m.size)>6*1024*1024)throw fail('legal_file_changed',409);const [bytes]=await file.download();if(bytes.length!==a.size||legalFileHash(bytes)!==a.sha256)throw fail('legal_file_changed',409);res.set({'Content-Type':'application/pdf','Content-Disposition':'attachment; filename="conditions.pdf"','Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff'}).send(bytes);}
 setRoutes(router:Router){const w=(f:any)=>(req:Request,res:Response,next:NextFunction)=>Promise.resolve(f(req,res)).catch(next),base='/api/platform/admin/legal';router.get(base,w(this.state));router.post(base+'/draft',w(this.create));router.post(base+'/resume-active',w(this.resume));router.post(base+'/document',w(this.save));router.post(base+'/publish',w(this.publish));router.get(base+'/file/:role/:language',w(async(req:Request,res:Response)=>{await this.admin(req);const legal=await this.read(),{id}=this.draft(legal);await this.sendFile(res,id,documentRouteParam(req,'role'),documentRouteParam(req,'language'),true);}));router.get('/api/legal/files/:release/:role/:language',w(async(req:Request,res:Response)=>this.sendFile(res,documentRouteParam(req,'release'),documentRouteParam(req,'role'),documentRouteParam(req,'language'))));}
}
